INSERT INTO flashcards (examId, specialty, pattern, answer, explanation, difficulty, status, front, back, category) VALUES
(1, 'Cardiovascular', '40M + hypertension + headache + proteinuria + seizure = ?', 'Hypertensive Crisis', 'Hypertensive emergency with end-organ damage. Requires immediate BP reduction per NICE CG180.', 'Hard', 'active', '40M + hypertension + headache + proteinuria + seizure = ?', 'Hypertensive Crisis', 'Cardiovascular'),
(1, 'Cardiovascular', '55F + dyspnoea + orthopnoea + S3 gallop = ?', 'Systolic Heart Failure', 'Systolic HF with reduced ejection fraction. NICE NG106 recommends ACE-I and beta-blockers.', 'Easy', 'active', '55F + dyspnoea + orthopnoea + S3 gallop = ?', 'Systolic Heart Failure', 'Cardiovascular'),
(1, 'Cardiovascular', '68M + dyspnoea + normal EF + diastolic dysfunction = ?', 'Diastolic Heart Failure', 'HFpEF with preserved ejection fraction. Common in hypertension and diabetes.', 'Medium', 'active', '68M + dyspnoea + normal EF + diastolic dysfunction = ?', 'Diastolic Heart Failure', 'Cardiovascular'),
(1, 'Cardiovascular', '42F + chest pain + troponin elevated + normal coronaries = ?', 'Myocarditis', 'Viral myocarditis with elevated troponin and normal coronaries. Requires supportive care.', 'Medium', 'active', '42F + chest pain + troponin elevated + normal coronaries = ?', 'Myocarditis', 'Cardiovascular'),
(1, 'Cardiovascular', '75M + syncope + systolic murmur + narrow pulse pressure = ?', 'Aortic Stenosis', 'Severe aortic stenosis with syncope. Requires urgent valve replacement.', 'Medium', 'active', '75M + syncope + systolic murmur + narrow pulse pressure = ?', 'Aortic Stenosis', 'Cardiovascular'),
(1, 'Cardiovascular', '38F + dyspnoea + diastolic murmur + AF = ?', 'Mitral Stenosis', 'Mitral stenosis with AF. NICE CG180 recommends anticoagulation and rate control.', 'Medium', 'active', '38F + dyspnoea + diastolic murmur + AF = ?', 'Mitral Stenosis', 'Cardiovascular'),
(1, 'Cardiovascular', '45M + chest pain + early diastolic murmur + aortic root dilatation = ?', 'Aortic Regurgitation', 'Aortic regurgitation with wide pulse pressure. Requires ACE-I and monitoring.', 'Medium', 'active', '45M + chest pain + early diastolic murmur + aortic root dilatation = ?', 'Aortic Regurgitation', 'Cardiovascular'),
(1, 'Cardiovascular', '52F + palpitations + holosystolic murmur + prominent JVP = ?', 'Mitral Regurgitation', 'Mitral regurgitation with prominent systolic murmur. May require valve repair.', 'Medium', 'active', '52F + palpitations + holosystolic murmur + prominent JVP = ?', 'Mitral Regurgitation', 'Cardiovascular'),
(1, 'Cardiovascular', '28M + sudden dyspnoea + chest pain + reduced breath sounds = ?', 'Spontaneous Pneumothorax', 'Pneumothorax presenting with acute dyspnoea. Requires chest X-ray and observation/intervention.', 'Easy', 'active', '28M + sudden dyspnoea + chest pain + reduced breath sounds = ?', 'Spontaneous Pneumothorax', 'Cardiovascular'),
(1, 'Cardiovascular', '65M + dyspnoea + elevated JVP + hepatomegaly + ascites = ?', 'Right Heart Failure', 'RV failure with signs of venous congestion. Often secondary to LV failure or pulmonary disease.', 'Medium', 'active', '65M + dyspnoea + elevated JVP + hepatomegaly + ascites = ?', 'Right Heart Failure', 'Cardiovascular'),
(1, 'Cardiovascular', '55M + palpitations + pre-syncope + WPW on ECG = ?', 'Wolff-Parkinson-White Syndrome', 'WPW with accessory pathway. Requires ablation if symptomatic.', 'Hard', 'active', '55M + palpitations + pre-syncope + WPW on ECG = ?', 'Wolff-Parkinson-White Syndrome', 'Cardiovascular'),
(1, 'Cardiovascular', '48F + palpitations + syncope + prolonged QT = ?', 'Long QT Syndrome', 'Congenital long QT with risk of torsades. Requires beta-blockers and ICD consideration.', 'Hard', 'active', '48F + palpitations + syncope + prolonged QT = ?', 'Long QT Syndrome', 'Cardiovascular'),
(1, 'Cardiovascular', '60M + leg pain + swelling + positive Homan\'s + D-dimer elevated = ?', 'Deep Vein Thrombosis (DVT)', 'DVT with positive D-dimer. Requires anticoagulation per NICE CG180.', 'Easy', 'active', '60M + leg pain + swelling + positive Homan\'s + D-dimer elevated = ?', 'Deep Vein Thrombosis (DVT)', 'Cardiovascular'),
(1, 'Cardiovascular', '55F + dyspnoea + chest pain + Wells score high + D-dimer elevated = ?', 'Pulmonary Embolism (PE)', 'PE with high clinical probability and elevated D-dimer. Requires CT pulmonary angiography.', 'Easy', 'active', '55F + dyspnoea + chest pain + Wells score high + D-dimer elevated = ?', 'Pulmonary Embolism (PE)', 'Cardiovascular'),
(1, 'Cardiovascular', '72M + sudden dyspnoea + hypoxia + crackles + elevated BNP = ?', 'Acute Decompensated Heart Failure', 'Acute HF exacerbation with pulmonary congestion. Requires diuretics and ACE-I.', 'Easy', 'active', '72M + sudden dyspnoea + hypoxia + crackles + elevated BNP = ?', 'Acute Decompensated Heart Failure', 'Cardiovascular'),
(1, 'Cardiovascular', '38M + fever + new murmur + positive blood cultures = ?', 'Infective Endocarditis', 'Endocarditis with fever and new murmur. Requires antibiotics per NICE NG180.', 'Medium', 'active', '38M + fever + new murmur + positive blood cultures = ?', 'Infective Endocarditis', 'Cardiovascular'),
(1, 'Cardiovascular', '52M + chest pain + pericardial friction rub + ST elevation = ?', 'Acute Pericarditis', 'Pericarditis with ST elevation and friction rub. Requires NSAIDs and colchicine.', 'Medium', 'active', '52M + chest pain + pericardial friction rub + ST elevation = ?', 'Acute Pericarditis', 'Cardiovascular'),
(1, 'Cardiovascular', '65M + dyspnoea + hypotension + muffled heart sounds = ?', 'Cardiac Tamponade', 'Tamponade with Beck\'s triad. Requires urgent pericardiocentesis.', 'Hard', 'active', '65M + dyspnoea + hypotension + muffled heart sounds = ?', 'Cardiac Tamponade', 'Cardiovascular'),
(1, 'Cardiovascular', '48F + chest pain + dyspnoea + anxiety + normal ECG = ?', 'Panic Disorder/Anxiety', 'Anxiety presenting with chest pain and dyspnoea. Requires reassurance and CBT.', 'Easy', 'active', '48F + chest pain + dyspnoea + anxiety + normal ECG = ?', 'Panic Disorder/Anxiety', 'Cardiovascular'),
(1, 'Cardiovascular', '70M + claudication + rest pain + tissue necrosis + absent pulses = ?', 'Critical Limb Ischaemia', 'Critical PAD with rest pain and tissue loss. Requires urgent vascular intervention.', 'Hard', 'active', '70M + claudication + rest pain + tissue necrosis + absent pulses = ?', 'Critical Limb Ischaemia', 'Cardiovascular');
INSERT INTO flashcards (examId, specialty, pattern, answer, explanation, difficulty, status, front, back, category) VALUES
(1, 'Respiratory', 'Child + barking cough + stridor + worse at night = ?', 'Croup (Laryngotracheobronchitis)', 'Viral croup with characteristic barking cough. NICE NG84 recommends dexamethasone.', 'Easy', 'active', 'Child + barking cough + stridor + worse at night = ?', 'Croup (Laryngotracheobronchitis)', 'Respiratory'),
(1, 'Respiratory', '3yo + fever + drooling + tripod position + stridor = ?', 'Epiglottitis', 'Epiglottitis with tripod positioning and drooling. Medical emergency requiring intubation.', 'Hard', 'active', '3yo + fever + drooling + tripod position + stridor = ?', 'Epiglottitis', 'Respiratory'),
(1, 'Respiratory', '2yo + fever + barking cough + inspiratory stridor = ?', 'Laryngitis', 'Viral laryngitis with cough and stridor. Usually self-limiting, supportive care.', 'Easy', 'active', '2yo + fever + barking cough + inspiratory stridor = ?', 'Laryngitis', 'Respiratory'),
(1, 'Respiratory', '28M + fever + productive cough + crackles + consolidation = ?', 'Community-Acquired Pneumonia (CAP)', 'CAP with fever and consolidation on CXR. NICE CG191 recommends amoxicillin first-line.', 'Easy', 'active', '28M + fever + productive cough + crackles + consolidation = ?', 'Community-Acquired Pneumonia (CAP)', 'Respiratory'),
(1, 'Respiratory', '65M + fever + dyspnoea + crackles + hospital admission = ?', 'Hospital-Acquired Pneumonia (HAP)', 'HAP in hospitalized patient. Requires broad-spectrum antibiotics.', 'Medium', 'active', '65M + fever + dyspnoea + crackles + hospital admission = ?', 'Hospital-Acquired Pneumonia (HAP)', 'Respiratory'),
(1, 'Respiratory', '42M + fever + night sweats + weight loss + cavitary lesion = ?', 'Tuberculosis (TB)', 'Pulmonary TB with cavitation. Requires 6-month isoniazid/rifampicin therapy.', 'Medium', 'active', '42M + fever + night sweats + weight loss + cavitary lesion = ?', 'Tuberculosis (TB)', 'Respiratory'),
(1, 'Respiratory', '55M + dyspnoea + cough + smoking history + reduced FEV1 = ?', 'Chronic Obstructive Pulmonary Disease (COPD)', 'COPD with airflow obstruction. NICE NG115 recommends smoking cessation and inhalers.', 'Easy', 'active', '55M + dyspnoea + cough + smoking history + reduced FEV1 = ?', 'Chronic Obstructive Pulmonary Disease (COPD)', 'Respiratory'),
(1, 'Respiratory', '35F + dyspnoea + wheeze + atopy + variable airflow obstruction = ?', 'Asthma', 'Asthma with reversible airflow obstruction. NICE NG80 recommends step-wise inhaler therapy.', 'Easy', 'active', '35F + dyspnoea + wheeze + atopy + variable airflow obstruction = ?', 'Asthma', 'Respiratory'),
(1, 'Respiratory', '48M + dyspnoea + bibasal crackles + reduced FVC + restrictive pattern = ?', 'Idiopathic Pulmonary Fibrosis (IPF)', 'IPF with restrictive pattern and bibasal fibrosis. Progressive, poor prognosis.', 'Medium', 'active', '48M + dyspnoea + bibasal crackles + reduced FVC + restrictive pattern = ?', 'Idiopathic Pulmonary Fibrosis (IPF)', 'Respiratory'),
(1, 'Respiratory', '52F + dyspnoea + cough + hilar lymphadenopathy + hypercalcaemia = ?', 'Sarcoidosis', 'Sarcoidosis with hilar lymphadenopathy and hypercalcaemia. Requires corticosteroids if symptomatic.', 'Medium', 'active', '52F + dyspnoea + cough + hilar lymphadenopathy + hypercalcaemia = ?', 'Sarcoidosis', 'Respiratory'),
(1, 'Respiratory', '65M + smoking + dyspnoea + weight loss + cavitary lesion = ?', 'Lung Cancer', 'Lung cancer with cavitation. Staging required; prognosis depends on stage.', 'Medium', 'active', '65M + smoking + dyspnoea + weight loss + cavitary lesion = ?', 'Lung Cancer', 'Respiratory'),
(1, 'Respiratory', '28M + sudden dyspnoea + chest pain + hypoxia + reduced breath sounds = ?', 'Pneumothorax', 'Spontaneous pneumothorax with acute dyspnoea. Requires chest X-ray and observation/intervention.', 'Easy', 'active', '28M + sudden dyspnoea + chest pain + hypoxia + reduced breath sounds = ?', 'Pneumothorax', 'Respiratory'),
(1, 'Respiratory', '55M + dyspnoea + chest pain + pleuritic + pleural effusion = ?', 'Pleural Effusion', 'Pleural effusion with dyspnoea and pleuritic pain. Requires investigation of cause.', 'Medium', 'active', '55M + dyspnoea + chest pain + pleuritic + pleural effusion = ?', 'Pleural Effusion', 'Respiratory'),
(1, 'Respiratory', '48M + fever + chest pain + pleuritic + consolidation = ?', 'Pneumonia with Pleurisy', 'Pneumonia with pleural inflammation. Requires antibiotics and NSAIDs.', 'Easy', 'active', '48M + fever + chest pain + pleuritic + consolidation = ?', 'Pneumonia with Pleurisy', 'Respiratory'),
(1, 'Respiratory', '42M + dyspnoea + orthopnoea + crackles + elevated BNP = ?', 'Pulmonary Oedema', 'Pulmonary oedema from heart failure. Requires diuretics and ACE-I.', 'Easy', 'active', '42M + dyspnoea + orthopnoea + crackles + elevated BNP = ?', 'Pulmonary Oedema', 'Respiratory'),
(1, 'Respiratory', '55F + dyspnoea + chest pain + Wells high + D-dimer elevated = ?', 'Pulmonary Embolism', 'PE with high clinical probability. Requires CT pulmonary angiography.', 'Easy', 'active', '55F + dyspnoea + chest pain + Wells high + D-dimer elevated = ?', 'Pulmonary Embolism', 'Respiratory'),
(1, 'Respiratory', '38M + fever + productive cough + night sweats + homeless = ?', 'Tuberculosis (Homeless)', 'TB in homeless population. Requires directly observed therapy.', 'Medium', 'active', '38M + fever + productive cough + night sweats + homeless = ?', 'Tuberculosis (Homeless)', 'Respiratory'),
(1, 'Respiratory', '32M + dyspnoea + orthopnoea + fever + new murmur = ?', 'Acute Heart Failure', 'Acute HF with pulmonary congestion. Requires diuretics and ACE-I.', 'Easy', 'active', '32M + dyspnoea + orthopnoea + fever + new murmur = ?', 'Acute Heart Failure', 'Respiratory'),
(1, 'Respiratory', '55M + cough + haemoptysis + weight loss + smoking = ?', 'Lung Cancer with Haemoptysis', 'Lung cancer presenting with haemoptysis. Requires urgent investigation.', 'Medium', 'active', '55M + cough + haemoptysis + weight loss + smoking = ?', 'Lung Cancer with Haemoptysis', 'Respiratory'),
(1, 'Respiratory', '48F + dyspnoea + cough + fever + immunocompromised = ?', 'Pneumocystis Pneumonia (PCP)', 'PCP in immunocompromised patient. Requires TMP-SMX therapy.', 'Hard', 'active', '48F + dyspnoea + cough + fever + immunocompromised = ?', 'Pneumocystis Pneumonia (PCP)', 'Respiratory'),
(1, 'Respiratory', '42M + dyspnoea + crackles + fever + recent travel = ?', 'Atypical Pneumonia', 'Atypical pneumonia (Mycoplasma/Chlamydia). Requires macrolide therapy.', 'Medium', 'active', '42M + dyspnoea + crackles + fever + recent travel = ?', 'Atypical Pneumonia', 'Respiratory'),
(1, 'Respiratory', '65M + dyspnoea + wheeze + smoking + reduced FEV1 = ?', 'COPD Exacerbation', 'COPD exacerbation with dyspnoea and wheeze. Requires bronchodilators and corticosteroids.', 'Easy', 'active', '65M + dyspnoea + wheeze + smoking + reduced FEV1 = ?', 'COPD Exacerbation', 'Respiratory'),
(1, 'Respiratory', '28M + dyspnoea + wheeze + atopy + peak flow reduced = ?', 'Asthma Exacerbation', 'Asthma exacerbation with dyspnoea and reduced peak flow. Requires bronchodilators and corticosteroids.', 'Easy', 'active', '28M + dyspnoea + wheeze + atopy + peak flow reduced = ?', 'Asthma Exacerbation', 'Respiratory'),
(1, 'Respiratory', '55F + dyspnoea + cough + fever + immunosuppressed = ?', 'Opportunistic Infection', 'Opportunistic infection in immunocompromised patient. Requires specific therapy.', 'Hard', 'active', '55F + dyspnoea + cough + fever + immunosuppressed = ?', 'Opportunistic Infection', 'Respiratory'),
(1, 'Respiratory', '48M + cough + sputum + fever + recent antibiotics = ?', 'Aspiration Pneumonia', 'Aspiration pneumonia with anaerobic organisms. Requires broad-spectrum antibiotics.', 'Medium', 'active', '48M + cough + sputum + fever + recent antibiotics = ?', 'Aspiration Pneumonia', 'Respiratory'),
(1, 'Respiratory', '35F + dyspnoea + cough + fever + recent flu = ?', 'Post-Viral Cough', 'Post-viral cough syndrome. Usually self-limiting, supportive care.', 'Easy', 'active', '35F + dyspnoea + cough + fever + recent flu = ?', 'Post-Viral Cough', 'Respiratory'),
(1, 'Respiratory', '52M + dyspnoea + crackles + reduced FVC + occupational history = ?', 'Occupational Lung Disease', 'Occupational lung disease (asbestos/silica). Requires workplace modification.', 'Medium', 'active', '52M + dyspnoea + crackles + reduced FVC + occupational history = ?', 'Occupational Lung Disease', 'Respiratory'),
(1, 'Respiratory', '45F + dyspnoea + cough + fever + recent travel = ?', 'Legionnaires Disease', 'Legionella pneumophila pneumonia. Requires fluoroquinolone therapy.', 'Hard', 'active', '45F + dyspnoea + cough + fever + recent travel = ?', 'Legionnaires Disease', 'Respiratory'),
(1, 'Respiratory', '38M + cough + sputum + fever + IV drug user = ?', 'Staph Aureus Pneumonia', 'Staphylococcus aureus pneumonia. Requires anti-staphylococcal antibiotics.', 'Medium', 'active', '38M + cough + sputum + fever + IV drug user = ?', 'Staph Aureus Pneumonia', 'Respiratory');
INSERT INTO flashcards (examId, specialty, pattern, answer, explanation, difficulty, status, front, back, category) VALUES
(1, 'Gastroenterology', '45M + epigastric pain + nausea + H.pylori positive = ?', 'Peptic Ulcer Disease (PUD)', 'PUD with H.pylori infection. NICE NG141 recommends triple therapy.', 'Easy', 'active', '45M + epigastric pain + nausea + H.pylori positive = ?', 'Peptic Ulcer Disease (PUD)', 'Gastroenterology'),
(1, 'Gastroenterology', '52M + epigastric pain + dyspepsia + NSAID use = ?', 'NSAID-Induced Ulcer', 'NSAID-related ulcer. Requires PPI and NSAID cessation.', 'Easy', 'active', '52M + epigastric pain + dyspepsia + NSAID use = ?', 'NSAID-Induced Ulcer', 'Gastroenterology'),
(1, 'Gastroenterology', '48M + haematemesis + melaena + cirrhosis = ?', 'Oesophageal Varices', 'Variceal bleeding in cirrhotic patient. Requires urgent endoscopy and banding.', 'Hard', 'active', '48M + haematemesis + melaena + cirrhosis = ?', 'Oesophageal Varices', 'Gastroenterology'),
(1, 'Gastroenterology', '55F + dysphagia + chest pain + normal endoscopy = ?', 'Achalasia', 'Achalasia with dysphagia and chest pain. Requires manometry and treatment.', 'Medium', 'active', '55F + dysphagia + chest pain + normal endoscopy = ?', 'Achalasia', 'Gastroenterology'),
(1, 'Gastroenterology', '42M + dysphagia + weight loss + smoking + alcohol = ?', 'Oesophageal Cancer', 'Oesophageal cancer with dysphagia and weight loss. Poor prognosis.', 'Medium', 'active', '42M + dysphagia + weight loss + smoking + alcohol = ?', 'Oesophageal Cancer', 'Gastroenterology'),
(1, 'Gastroenterology', '38F + heartburn + regurgitation + worse lying down = ?', 'Gastro-Oesophageal Reflux Disease (GORD)', 'GORD with heartburn and regurgitation. NICE NG184 recommends PPI therapy.', 'Easy', 'active', '38F + heartburn + regurgitation + worse lying down = ?', 'Gastro-Oesophageal Reflux Disease (GORD)', 'Gastroenterology'),
(1, 'Gastroenterology', '52M + nausea + vomiting + abdominal distension + obstruction = ?', 'Bowel Obstruction', 'Mechanical bowel obstruction with vomiting and distension. Requires surgical intervention.', 'Medium', 'active', '52M + nausea + vomiting + abdominal distension + obstruction = ?', 'Bowel Obstruction', 'Gastroenterology'),
(1, 'Gastroenterology', '48F + diarrhoea + abdominal pain + fever + bloody stool = ?', 'Inflammatory Bowel Disease (IBD)', 'IBD with bloody diarrhoea and fever. Requires colonoscopy and immunosuppression.', 'Medium', 'active', '48F + diarrhoea + abdominal pain + fever + bloody stool = ?', 'Inflammatory Bowel Disease (IBD)', 'Gastroenterology'),
(1, 'Gastroenterology', '55M + diarrhoea + weight loss + anaemia + recent antibiotics = ?', 'Clostridium Difficile Infection (CDI)', 'CDI with diarrhoea after antibiotics. Requires vancomycin or fidaxomicin.', 'Medium', 'active', '55M + diarrhoea + weight loss + anaemia + recent antibiotics = ?', 'Clostridium Difficile Infection (CDI)', 'Gastroenterology'),
(1, 'Gastroenterology', '42M + acute abdominal pain + fever + elevated lipase = ?', 'Acute Pancreatitis', 'Acute pancreatitis with elevated lipase. Requires supportive care and investigation of cause.', 'Easy', 'active', '42M + acute abdominal pain + fever + elevated lipase = ?', 'Acute Pancreatitis', 'Gastroenterology'),
(1, 'Gastroenterology', '55M + chronic abdominal pain + steatorrhoea + diabetes = ?', 'Chronic Pancreatitis', 'Chronic pancreatitis with malabsorption and diabetes. Requires enzyme replacement.', 'Medium', 'active', '55M + chronic abdominal pain + steatorrhoea + diabetes = ?', 'Chronic Pancreatitis', 'Gastroenterology'),
(1, 'Gastroenterology', '48F + right upper quadrant pain + fever + jaundice = ?', 'Acute Cholecystitis', 'Acute cholecystitis with fever and RUQ pain. Requires ultrasound and cholecystectomy.', 'Easy', 'active', '48F + right upper quadrant pain + fever + jaundice = ?', 'Acute Cholecystitis', 'Gastroenterology'),
(1, 'Gastroenterology', '52M + jaundice + pale stool + dark urine + weight loss = ?', 'Pancreatic Cancer', 'Pancreatic cancer with painless jaundice. Poor prognosis.', 'Medium', 'active', '52M + jaundice + pale stool + dark urine + weight loss = ?', 'Pancreatic Cancer', 'Gastroenterology'),
(1, 'Gastroenterology', '45F + jaundice + fever + right upper quadrant pain = ?', 'Cholangitis', 'Cholangitis with fever and jaundice. Requires urgent ERCP.', 'Medium', 'active', '45F + jaundice + fever + right upper quadrant pain = ?', 'Cholangitis', 'Gastroenterology'),
(1, 'Gastroenterology', '38M + abdominal pain + diarrhoea + weight loss + fever = ?', 'Crohn\'s Disease', 'Crohn\'s disease with abdominal pain and diarrhoea. Requires immunosuppression.', 'Medium', 'active', '38M + abdominal pain + diarrhoea + weight loss + fever = ?', 'Crohn\'s Disease', 'Gastroenterology'),
(1, 'Gastroenterology', '55F + bloody diarrhoea + abdominal pain + fever = ?', 'Ulcerative Colitis', 'Ulcerative colitis with bloody diarrhoea. Requires immunosuppression.', 'Medium', 'active', '55F + bloody diarrhoea + abdominal pain + fever = ?', 'Ulcerative Colitis', 'Gastroenterology'),
(1, 'Gastroenterology', '48M + diarrhoea + weight loss + anaemia + coeliac serology positive = ?', 'Coeliac Disease', 'Coeliac disease with malabsorption. Requires gluten-free diet.', 'Easy', 'active', '48M + diarrhoea + weight loss + anaemia + coeliac serology positive = ?', 'Coeliac Disease', 'Gastroenterology'),
(1, 'Gastroenterology', '42F + diarrhoea + abdominal bloating + lactose intolerance = ?', 'Lactose Intolerance', 'Lactose intolerance with diarrhoea and bloating. Requires dietary modification.', 'Easy', 'active', '42F + diarrhoea + abdominal bloating + lactose intolerance = ?', 'Lactose Intolerance', 'Gastroenterology'),
(1, 'Gastroenterology', '52M + constipation + abdominal pain + weight loss + anaemia = ?', 'Colorectal Cancer', 'Colorectal cancer with constipation and anaemia. Requires colonoscopy.', 'Medium', 'active', '52M + constipation + abdominal pain + weight loss + anaemia = ?', 'Colorectal Cancer', 'Gastroenterology'),
(1, 'Gastroenterology', '45F + acute abdominal pain + fever + rebound tenderness = ?', 'Acute Appendicitis', 'Appendicitis with acute pain and peritonitis. Requires appendicectomy.', 'Easy', 'active', '45F + acute abdominal pain + fever + rebound tenderness = ?', 'Acute Appendicitis', 'Gastroenterology'),
(1, 'Gastroenterology', '38M + haemorrhoids + blood on toilet paper + anal pain = ?', 'Internal Haemorrhoids', 'Internal haemorrhoids with bleeding and pain. Requires conservative management.', 'Easy', 'active', '38M + haemorrhoids + blood on toilet paper + anal pain = ?', 'Internal Haemorrhoids', 'Gastroenterology'),
(1, 'Gastroenterology', '55M + constipation + abdominal pain + fever + elevated WCC = ?', 'Diverticulitis', 'Diverticulitis with fever and abdominal pain. Requires antibiotics and dietary modification.', 'Medium', 'active', '55M + constipation + abdominal pain + fever + elevated WCC = ?', 'Diverticulitis', 'Gastroenterology'),
(1, 'Gastroenterology', '48F + diarrhoea + abdominal pain + recent travel = ?', 'Traveller\'s Diarrhoea', 'Traveller\'s diarrhoea from enterotoxigenic E.coli. Usually self-limiting.', 'Easy', 'active', '48F + diarrhoea + abdominal pain + recent travel = ?', 'Traveller\'s Diarrhoea', 'Gastroenterology'),
(1, 'Gastroenterology', '42M + diarrhoea + fever + food poisoning history = ?', 'Bacterial Gastroenteritis', 'Bacterial gastroenteritis with diarrhoea and fever. Usually self-limiting.', 'Easy', 'active', '42M + diarrhoea + fever + food poisoning history = ?', 'Bacterial Gastroenteritis', 'Gastroenterology'),
(1, 'Gastroenterology', '35F + vomiting + diarrhoea + fever + recent viral illness = ?', 'Viral Gastroenteritis', 'Viral gastroenteritis with vomiting and diarrhoea. Requires supportive care.', 'Easy', 'active', '35F + vomiting + diarrhoea + fever + recent viral illness = ?', 'Viral Gastroenteritis', 'Gastroenterology'),
(1, 'Gastroenterology', '52M + jaundice + hepatomegaly + elevated LFTs + alcohol = ?', 'Alcoholic Liver Disease', 'Alcoholic liver disease with jaundice. Requires alcohol cessation.', 'Medium', 'active', '52M + jaundice + hepatomegaly + elevated LFTs + alcohol = ?', 'Alcoholic Liver Disease', 'Gastroenterology'),
(1, 'Gastroenterology', '48F + jaundice + elevated ALT + positive anti-HCV = ?', 'Hepatitis C', 'Hepatitis C with jaundice and elevated transaminases. Requires antiviral therapy.', 'Medium', 'active', '48F + jaundice + elevated ALT + positive anti-HCV = ?', 'Hepatitis C', 'Gastroenterology'),
(1, 'Gastroenterology', '42M + jaundice + fever + elevated ALT + positive HBsAg = ?', 'Hepatitis B', 'Hepatitis B with jaundice and fever. Requires monitoring and antiviral therapy.', 'Medium', 'active', '42M + jaundice + fever + elevated ALT + positive HBsAg = ?', 'Hepatitis B', 'Gastroenterology'),
(1, 'Gastroenterology', '55M + ascites + hepatomegaly + varices + cirrhosis = ?', 'Cirrhosis', 'Cirrhosis with ascites and portal hypertension. Requires monitoring for complications.', 'Medium', 'active', '55M + ascites + hepatomegaly + varices + cirrhosis = ?', 'Cirrhosis', 'Gastroenterology');
INSERT INTO flashcards (examId, specialty, pattern, answer, explanation, difficulty, status, front, back, category) VALUES
(1, 'Neurology', '55M + sudden severe headache + neck stiffness + photophobia = ?', 'Meningitis', 'Meningitis with classic triad. Requires urgent LP and antibiotics.', 'Easy', 'active', '55M + sudden severe headache + neck stiffness + photophobia = ?', 'Meningitis', 'Neurology'),
(1, 'Neurology', '48M + sudden severe headache + focal neurological deficit = ?', 'Subarachnoid Haemorrhage (SAH)', 'SAH with thunderclap headache and focal deficit. Requires urgent CT and neurosurgery.', 'Hard', 'active', '48M + sudden severe headache + focal neurological deficit = ?', 'Subarachnoid Haemorrhage (SAH)', 'Neurology'),
(1, 'Neurology', '65M + sudden weakness + facial droop + speech difficulty = ?', 'Acute Stroke', 'Acute ischaemic stroke with focal deficit. Requires urgent thrombolysis.', 'Easy', 'active', '65M + sudden weakness + facial droop + speech difficulty = ?', 'Acute Stroke', 'Neurology'),
