(1, 'Neurology', '35M + first seizure + no prior history = ?', 'First Seizure', 'First unprovoked seizure. Requires investigation and EEG.', 'Medium', 'active', '35M + first seizure + no prior history = ?', 'First Seizure', 'Neurology'),
(1, 'Neurology', '48F + recurrent seizures + on antiepileptic medication = ?', 'Epilepsy', 'Epilepsy with recurrent seizures. Requires medication optimization.', 'Easy', 'active', '48F + recurrent seizures + on antiepileptic medication = ?', 'Epilepsy', 'Neurology'),
(1, 'Neurology', '52M + tremor + rigidity + bradykinesia = ?', 'Parkinson\'s Disease', 'Parkinson\'s disease with classic triad. Requires dopamine agonists.', 'Easy', 'active', '52M + tremor + rigidity + bradykinesia = ?', 'Parkinson\'s Disease', 'Neurology'),
